/*
 * A103369  Number in the 2-digitaddition sequence at which the eventually
 *          periodic part starts.
 * https://oeis.org/A103369
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = first repeated term in the 2-digit-addition sequence. The
 *            sequence is generated by the function f(x) = x*x if x < 10 f(x)
 *            = sum of squares of the decimal digits of x otherwise. a(n) is
 *            the value that first reappears while iterating f from the start
 *            value n. It is found by Floyd’s cycle‑fin...
 * Range:     u8 n <= 456, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   next_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/next_seq.h"

seq_t a(idx_t n)
{
    /* First phase: find a meeting point inside the cycle. */
    seq_t tortoise = next_seq((seq_t)n);
    seq_t hare     = next_seq(next_seq((seq_t)n));
    while (tortoise != hare) {
        tortoise = next_seq(tortoise);
        hare = next_seq(next_seq(hare));
    }

    /* Second phase: find the start of the cycle (first repeated value). */
    tortoise = (seq_t)n;
    while (tortoise != hare) {
        tortoise = next_seq(tortoise);
        hare = next_seq(hare);
    }
    return tortoise;   /* the first repeated value */
}
